# Generated by the AMP "Vintage Story (Stratum + Nimbus)" template.
param([Parameter(Mandatory = $true)][string]$Root)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

if ($env:NIMBUS_INSTALL -and $env:NIMBUS_INSTALL.Trim().ToLowerInvariant() -ne 'true') {
    Write-Host '[AMP] Nimbus server mod installation is disabled'
    exit 0
}

$repo = 'StratumServer/Nimbus'
$headers = @{ 'User-Agent' = 'AMP-Stratum-Template'; 'Accept' = 'application/vnd.github+json' }
if ($env:GITHUB_TOKEN) { $headers['Authorization'] = "Bearer $($env:GITHUB_TOKEN)" }

$tag = if ($env:NIMBUS_MOD_VERSION) { $env:NIMBUS_MOD_VERSION.Trim() } else { '' }
if ($tag -eq '') {
    $channel = if ($env:NIMBUS_CHANNEL) { $env:NIMBUS_CHANNEL } else { 'stable' }
    $releases = Invoke-RestMethod -Headers $headers -Uri "https://api.github.com/repos/$repo/releases?per_page=100"
    $candidates = @($releases | Where-Object { -not $_.draft })
    if ($channel -ne 'prerelease') { $candidates = @($candidates | Where-Object { -not $_.prerelease }) }
    if ($candidates.Count -eq 0) { throw 'No Nimbus release found' }
    $tag = $candidates[0].tag_name
}
if (-not $tag.StartsWith('v')) { $tag = "v$tag" }

$modDir = Join-Path $Root 'data\Mods\Nimbus.ServerMod'
New-Item -ItemType Directory -Force -Path (Join-Path $Root 'data\ModConfig') | Out-Null
$marker = Join-Path $modDir '.amp-nimbus-release'
if ((Test-Path $marker) -and ((Get-Content $marker -Raw).Trim() -eq $tag)) {
    Write-Host "[AMP] Nimbus server mod already on $tag"
    exit 0
}

$zip = Join-Path $Root 'nimbus-mod.zip'
$url = "https://github.com/$repo/releases/download/$tag/Nimbus.ServerMod-$tag.zip"
Write-Host "[AMP] downloading $url"
Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $zip
if (Test-Path $modDir) { Remove-Item $modDir -Recurse -Force }
New-Item -ItemType Directory -Force -Path $modDir | Out-Null
Expand-Archive -Path $zip -DestinationPath $modDir -Force
Remove-Item $zip -Force
Set-Content -Path $marker -Value $tag -NoNewline
Write-Host "[AMP] installed Nimbus server mod $tag into $modDir"

# Generated by the AMP "Vintage Story (Stratum + Nimbus)" template.
# Repairs WorldConfig.SaveFileLocation in data\serverconfig.json before every start.
# Vintage Story stores an absolute path to the .vcdbs world file in that key and never
# recalculates it, so an empty, missing or stale value makes the server abort with
# "Unable to open or create savegame". This script puts a valid path back without
# touching or reformatting any other part of the file.
param([Parameter(Mandatory = $true)][string]$DataDir)

$ErrorActionPreference = 'Stop'

$DataDir = $DataDir.TrimEnd('\', '/')
$cfg = Join-Path $DataDir 'serverconfig.json'
if (-not (Test-Path -LiteralPath $cfg)) { exit 0 }

$saves = Join-Path $DataDir 'Saves'
$desired = Join-Path $saves 'default.vcdbs'
if ((Test-Path -LiteralPath $saves) -and -not (Test-Path -LiteralPath $desired)) {
    $found = @(Get-ChildItem -LiteralPath $saves -Filter '*.vcdbs' -File -ErrorAction SilentlyContinue)
    if ($found.Count -eq 1) { $desired = $found[0].FullName }
}

$text = [IO.File]::ReadAllText($cfg)
$rx = '"SaveFileLocation"\s*:\s*"((?:[^"\\]|\\.)*)"'
$m = [regex]::Match($text, $rx)

$need = 0
if (-not $m.Success) {
    $need = 2
}
else {
    $cur = $m.Groups[1].Value -replace '\\\\', '\'
    if ([string]::IsNullOrWhiteSpace($cur)) {
        $need = 1
    }
    else {
        $parent = Split-Path -Path $cur -Parent
        if ([string]::IsNullOrWhiteSpace($parent) -or -not (Test-Path -LiteralPath $parent)) {
            Write-Output "[AMP] serverconfig.json points at $cur but that folder does not exist on this system"
            $need = 1
        }
    }
}

if ($need -eq 0) { exit 0 }

New-Item -ItemType Directory -Path $saves -Force | Out-Null
$bs = [string][char]92
$dl = [string][char]36
$esc = $desired.Replace($bs, $bs + $bs)
$rep = $esc.Replace($dl, $dl + $dl)

if ($need -eq 1) {
    $text = [regex]::new($rx).Replace($text, ('"SaveFileLocation": "' + $rep + '"'), 1)
}
elseif ($text -match '"WorldConfig"\s*:\s*\{') {
    $text = [regex]::new('"WorldConfig"\s*:\s*\{').Replace($text, ('$0"SaveFileLocation": "' + $rep + '",'), 1)
}
else {
    Write-Warning "[AMP] no WorldConfig section in $cfg, cannot repair the save file location"
    exit 0
}

[IO.File]::WriteAllText($cfg, $text, (New-Object Text.UTF8Encoding $false))
Write-Output "[AMP] repaired SaveFileLocation in serverconfig.json -> $desired"

# Generated by the AMP "Vintage Story (Stratum + Nimbus)" template.
# Renders data\ModConfig\nimbus-server.json from the instance settings before every start.
param([Parameter(Mandatory = $true)][string]$Target)

$ErrorActionPreference = 'Stop'

function Get-Env([string]$name, [string]$fallback = '') {
    $v = [Environment]::GetEnvironmentVariable($name)
    if ([string]::IsNullOrWhiteSpace($v)) { return $fallback }
    return $v
}
function Get-Bool([string]$name, [bool]$fallback) {
    $v = Get-Env $name ''
    if ($v -eq '') { return $fallback }
    return ($v.Trim().ToLowerInvariant() -eq 'true')
}
function Split-List([string]$value, [string]$sep) {
    if ([string]::IsNullOrWhiteSpace($value)) { return @() }
    return @($value.Split($sep) | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' })
}

if (-not (Get-Bool 'NIMBUS_WRITE_CONFIG' $true)) {
    Write-Host "[AMP] Nimbus config management is off; leaving $Target as it is"
    exit 0
}

$dir = Split-Path -Parent $Target
if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }

$port = 0
[void][int]::TryParse((Get-Env 'NIMBUS_PUBLIC_PORT' '0'), [ref]$port)
if ($port -le 0) { [void][int]::TryParse((Get-Env 'NIMBUS_FALLBACK_PORT' '42420'), [ref]$port) }
if ($port -le 0) { $port = 42420 }

$host_ = Get-Env 'NIMBUS_PUBLIC_HOST' '127.0.0.1'

$shortcuts = @()
foreach ($raw in (Split-List (Get-Env 'NIMBUS_SHORTCUTS' '') ';')) {
    $privilege = 'chat'
    $body = $raw
    $at = $raw.LastIndexOf('@')
    if ($at -ge 0) {
        $body = $raw.Substring(0, $at)
        $privilege = $raw.Substring($at + 1).Trim()
        if ($privilege -eq '') { $privilege = 'chat' }
    }
    $kv = $body.Split('=', 2)
    $name = $kv[0].Trim().TrimStart('/')
    $targets = @()
    if ($kv.Length -gt 1) { $targets = Split-List $kv[1] '|' }
    if ($name -ne '' -and $targets.Count -gt 0) {
        $shortcuts += [ordered]@{ Name = $name; Targets = $targets; Privilege = $privilege; Description = '' }
    }
}

# Windows PowerShell 5.1 turns single element arrays into scalars when it converts to
# JSON, which would produce "Targets": "hub" instead of a list, so the JSON is written by
# hand here. Keep it that way.
function Esc([string]$s) {
    if ($null -eq $s) { return '""' }
    $s = $s.Replace('\', '\\').Replace('"', '\"').Replace("`r", '\r').Replace("`n", '\n').Replace("`t", '\t')
    return '"' + $s + '"'
}
function JList($items) {
    if (-not $items -or @($items).Count -eq 0) { return '[]' }
    return '[' + ((@($items) | ForEach-Object { Esc $_ }) -join ', ') + ']'
}
function JBool([bool]$b) { if ($b) { return 'true' } else { return 'false' } }

$serverId = Get-Env 'NIMBUS_SERVER_ID' ''
$registryUrl = Get-Env 'NIMBUS_REGISTRY_URL' ''
$transferMode = Get-Env 'NIMBUS_TRANSFER_MODE' 'redirect'
$secret = Get-Env 'NIMBUS_SHARED_SECRET' ''

$sc = @()
foreach ($s in $shortcuts) {
    $sc += @"
    {
      "Name": $(Esc $s.Name),
      "Targets": $(JList $s.Targets),
      "Privilege": $(Esc $s.Privilege),
      "Description": ""
    }
"@
}

$json = @"
{
  "Enabled": $(JBool (Get-Bool 'NIMBUS_ENABLED' $true)),
  "ServerId": $(Esc $serverId),
  "DisplayName": $(Esc (Get-Env 'NIMBUS_DISPLAY_NAME' '')),
  "PublicHost": $(Esc $host_),
  "PublicPort": $port,
  "Tags": $(JList (Split-List (Get-Env 'NIMBUS_TAGS' '') ',')),
  "RegistryUrl": $(Esc $registryUrl),
  "SharedSecret": $(Esc $secret),
  "HeartbeatIntervalSeconds": $([int](Get-Env 'NIMBUS_HEARTBEAT' '5')),
  "RegistryHttpTimeoutSeconds": $([int](Get-Env 'NIMBUS_HTTP_TIMEOUT' '5')),
  "Maintenance": $(JBool (Get-Bool 'NIMBUS_MAINTENANCE' $false)),
  "ReservationRequired": $(JBool (Get-Bool 'NIMBUS_RESERVATION_REQUIRED' $true)),
  "FailClosedWhenRegistryUnreachable": $(JBool (Get-Bool 'NIMBUS_FAIL_CLOSED' $false)),
  "AllowPlayerServerCommand": $(JBool (Get-Bool 'NIMBUS_ALLOW_SERVER_COMMAND' $true)),
  "TransferMode": $(Esc $transferMode),
  "SeamlessPrepareAckTimeoutSeconds": $([int](Get-Env 'NIMBUS_SEAMLESS_ACK' '8')),
  "ShortcutCommands": [
$($sc -join ",`r`n")
  ]
}
"@

[IO.File]::WriteAllText($Target, $json, (New-Object Text.UTF8Encoding($false)))
Write-Host ("[AMP] wrote {0}  serverId={1} advertised={2}:{3} registry={4} transferMode={5}" -f $Target, $serverId, $host_, $port, $registryUrl, $transferMode)
if ([string]::IsNullOrWhiteSpace($secret)) {
    Write-Host "[AMP] WARNING: no registry shared secret is set, so heartbeats will be rejected. Copy the secret from the proxy or registry into this instance's Nimbus settings."
}
